'use strict';
/*
 * =====================================================================
 *  ALHIJJAB MARKETING — Official Real Estate Website
 *  Single-file application: run with `node index.js`
 *
 *  - Public website (Home, Properties, Margalla Enclave, About, Contact)
 *  - Office administrator interface at /office
 *  - JSON property storage + uploaded photos in DATA_DIR (default /data)
 *  - Node.js built-in modules only. No npm install required.
 *
 *  Environment variables (Railway → Variables):
 *    ADMIN_PASSWORD  required for office login (min 12 characters)
 *    DATA_DIR        optional, defaults to /data (mount a Railway Volume here)
 *    PORT            provided by Railway
 *
 *  The property inventory starts EMPTY. No sample or demo data exists.
 *  Runtime data (properties.json, images/) is created automatically.
 * =====================================================================
 */

const http = require('http');
const fs = require('fs');
const fsp = fs.promises;
const path = require('path');
const crypto = require('crypto');

/* =====================================================================
 * 1. CONFIGURATION
 * ===================================================================== */

const PORT = parseInt(process.env.PORT, 10) || 3000;
const HOST = '0.0.0.0';
const DATA_DIR = path.resolve(process.env.DATA_DIR || '/data');
const DB_FILE = path.join(DATA_DIR, 'properties.json');
const IMG_DIR = path.join(DATA_DIR, 'images');

const ADMIN_PASSWORD = typeof process.env.ADMIN_PASSWORD === 'string' ? process.env.ADMIN_PASSWORD : '';
const MIN_PASSWORD_LENGTH = 12;
const ADMIN_ENABLED = ADMIN_PASSWORD.length >= MIN_PASSWORD_LENGTH;

const SESSION_TTL_MS = 8 * 60 * 60 * 1000;      // 8 hours
const MAX_SESSIONS = 50;
const LOGIN_MAX_FAILS = 5;                       // per IP per window
const LOGIN_WINDOW_MS = 15 * 60 * 1000;
const MAX_JSON_BYTES = 64 * 1024;
const MAX_IMAGE_BYTES = 8 * 1024 * 1024;         // 8 MB per photo
const MAX_IMAGES_PER_PROPERTY = 15;

/*
 * LOGO: paste the Alhijjab Marketing logo as a base64 data URI between the
 * quotes, e.g. 'data:image/png;base64,iVBORw0KGgo...'.
 * While empty, a neutral diamond mark with the brand name is shown.
 */
const LOGO_DATA_URI = 'data:image/png;base64,';
const FAVICON_DATA_URI = 'data:image/png;base64,';

const CONTACT = {
  name: 'Alhijjab Marketing',
  location: 'Islamabad, Pakistan',
  phoneDisplay: '0320 7111555',
  tel: 'tel:+923207111555',
  waDisplay: '+92 320 7111555',
  wa: 'https://wa.me/923207111555'
};

const PROPERTY_TYPES = ['Residential Plot', 'Commercial Plot', 'House', 'Apartment', 'Commercial Property', 'Farm House', 'Other'];
const PURPOSES = ['For Sale', 'For Rent'];

/*
 * Approved Islamabad locations (backend-enforced).
 * confirm:false → CDA sector / area inside Islamabad Capital Territory.
 * confirm:true  → named development or corridor whose extent may cross the
 *                 ICT boundary; the administrator must confirm that the
 *                 specific property lies within Islamabad Capital Territory.
 */
const SECTORS = [
  'Blue Area', 'C-14', 'C-15', 'C-16', 'D-12', 'D-13', 'E-7', 'E-11', 'E-12',
  'F-5', 'F-6', 'F-7', 'F-8', 'F-10', 'F-11', 'F-13', 'F-14',
  'G-5', 'G-6', 'G-7', 'G-8', 'G-9', 'G-10', 'G-11', 'G-12', 'G-13', 'G-14', 'G-15', 'G-16',
  'H-8', 'H-9', 'H-10', 'H-11', 'H-12', 'H-13',
  'I-8', 'I-9', 'I-10', 'I-11', 'I-12', 'I-14', 'I-15', 'I-16',
  'B-17'
];
const CONFIRM_AREAS = [
  'DHA Islamabad', 'Margalla Enclave', 'Gulberg Greens', 'Gulberg Residencia',
  'Park View City', 'Top City', 'Mumtaz City', 'Bani Gala', 'Chak Shahzad',
  'Park Road', 'Islamabad Expressway', 'Kashmir Highway'
];
const AREAS = SECTORS.map(n => ({ name: n, confirm: false }))
  .concat(CONFIRM_AREAS.map(n => ({ name: n, confirm: true })));
const AREA_MAP = new Map(AREAS.map(a => [a.name, a]));

// Addresses mentioning another city are rejected.
const OTHER_CITIES = [
  'rawalpindi', 'pindi', 'lahore', 'karachi', 'peshawar', 'murree', 'taxila', 'attock',
  'wah cantt', 'gujar khan', 'fateh jang', 'gwadar', 'faisalabad', 'multan', 'abbottabad',
  'chakwal', 'jhelum', 'hassan abdal', 'quetta', 'sialkot', 'gujranwala', 'mardan', 'kahuta'
];
const OTHER_CITY_RE = new RegExp('\\b(' + OTHER_CITIES.map(c => c.replace(/ /g, '\\s+')).join('|') + ')\\b', 'i');

const IMAGE_TYPES = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' };
const IMAGE_MIME_BY_EXT = { jpg: 'image/jpeg', png: 'image/png', webp: 'image/webp' };
const IMAGE_NAME_RE = /^[a-f0-9]{32}\.(jpg|png|webp)$/;
const ID_RE = /^[a-f0-9]{16}$/;

/* =====================================================================
 * 2. STORAGE (JSON file + image directory, atomic writes)
 * ===================================================================== */

let properties = [];          // always loaded from disk, never seeded
let storageOk = false;
let storageError = '';

function initStorage() {
  try {
    fs.mkdirSync(IMG_DIR, { recursive: true });
  } catch (e) {
    storageError = 'Cannot create data directory ' + DATA_DIR + ' (' + e.code + ').';
    console.error('[storage] ' + storageError);
    return;
  }
  try {
    if (!fs.existsSync(DB_FILE)) {
      const tmp = DB_FILE + '.init.tmp';
      fs.writeFileSync(tmp, '[]\n', { flag: 'w' });
      fs.renameSync(tmp, DB_FILE);
      console.log('[storage] Created empty property database at ' + DB_FILE);
    }
  } catch (e) {
    storageError = 'Cannot create property database file (' + e.code + ').';
    console.error('[storage] ' + storageError);
    return;
  }
  try {
    const raw = fs.readFileSync(DB_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed) || !parsed.every(r => r && typeof r === 'object' && typeof r.id === 'string')) {
      throw new Error('unexpected structure');
    }
    properties = parsed.map(r => Object.assign({ images: [], features: [] }, r));
    storageOk = true;
    console.log('[storage] Loaded ' + properties.length + ' property record(s) from ' + DB_FILE);
  } catch (e) {
    storageError = 'The property data file ' + DB_FILE + ' is unreadable or malformed. ' +
      'It has NOT been modified. Restore or repair it, then restart the service.';
    console.error('[storage] ' + storageError + ' (' + e.message + ')');
  }
  // Clean up abandoned partial uploads from an earlier crash.
  try {
    for (const f of fs.readdirSync(IMG_DIR)) {
      if (f.endsWith('.part')) fs.unlink(path.join(IMG_DIR, f), () => {});
    }
  } catch (e) { /* non-fatal */ }
}

async function atomicWrite(file, data) {
  const tmp = file + '.' + crypto.randomBytes(6).toString('hex') + '.tmp';
  const fh = await fsp.open(tmp, 'w');
  try {
    await fh.writeFile(data);
    await fh.sync();
  } finally {
    await fh.close();
  }
  await fsp.rename(tmp, file);
}

// All mutations are serialized. Changes are applied to a copy and only
// become live after the file has been written successfully.
let mutationLock = Promise.resolve();
function mutate(fn) {
  const run = mutationLock.then(async () => {
    if (!storageOk) throw httpError(503, 'Storage is unavailable: ' + storageError);
    const next = JSON.parse(JSON.stringify(properties));
    const result = fn(next);
    await atomicWrite(DB_FILE, JSON.stringify(next, null, 2) + '\n');
    properties = next;
    return result;
  });
  mutationLock = run.catch(() => {});
  return run;
}

function volumeWarning() {
  if (process.env.RAILWAY_ENVIRONMENT || process.env.RAILWAY_PROJECT_ID) {
    const mount = process.env.RAILWAY_VOLUME_MOUNT_PATH;
    if (!mount) return 'No Railway Volume detected. Properties and photos will be lost on redeploy. Attach a Volume mounted at ' + DATA_DIR + '.';
    const rel = path.relative(path.resolve(mount), DATA_DIR);
    if (rel.startsWith('..') || path.isAbsolute(rel)) return 'DATA_DIR (' + DATA_DIR + ') is not inside the Railway Volume (' + mount + '). Data will be lost on redeploy.';
  }
  return '';
}

/* =====================================================================
 * 3. SESSIONS, AUTHENTICATION, RATE LIMITING
 * ===================================================================== */

const sessions = new Map();    // sha256(token) -> { exp, csrf }
const loginFails = new Map();  // ip -> { count, first }

function sha256(s) { return crypto.createHash('sha256').update(String(s)).digest(); }

function safeEqualStr(a, b) {
  return crypto.timingSafeEqual(sha256(a), sha256(b));
}

function passwordMatches(input) {
  if (!ADMIN_ENABLED || typeof input !== 'string') return false;
  return safeEqualStr(input, ADMIN_PASSWORD);
}

function createSession() {
  if (sessions.size >= MAX_SESSIONS) {
    let oldestKey = null, oldestExp = Infinity;
    for (const [k, s] of sessions) if (s.exp < oldestExp) { oldestExp = s.exp; oldestKey = k; }
    if (oldestKey) sessions.delete(oldestKey);
  }
  const token = crypto.randomBytes(32).toString('hex');
  const csrf = crypto.randomBytes(24).toString('hex');
  sessions.set(sha256(token).toString('hex'), { exp: Date.now() + SESSION_TTL_MS, csrf });
  return { token, csrf };
}

function parseCookies(req) {
  const out = {};
  const h = req.headers.cookie;
  if (!h) return out;
  for (const part of h.split(';')) {
    const i = part.indexOf('=');
    if (i < 0) continue;
    const k = part.slice(0, i).trim();
    const v = part.slice(i + 1).trim();
    if (k) out[k] = v;
  }
  return out;
}

function getSession(req) {
  const token = parseCookies(req).ahm_sid;
  if (!token || !/^[a-f0-9]{64}$/.test(token)) return null;
  const key = sha256(token).toString('hex');
  const s = sessions.get(key);
  if (!s) return null;
  if (s.exp < Date.now()) { sessions.delete(key); return null; }
  return { key, ...s };
}

function isHttps(req) {
  const p = String(req.headers['x-forwarded-proto'] || '').split(',')[0].trim().toLowerCase();
  return p === 'https' || !!req.socket.encrypted;
}

function sessionCookie(req, token, maxAgeSec) {
  return 'ahm_sid=' + token + '; Path=/; HttpOnly; SameSite=Strict; Max-Age=' + maxAgeSec + (isHttps(req) ? '; Secure' : '');
}

function clientIp(req) {
  const fwd = String(req.headers['x-forwarded-for'] || '').split(',')[0].trim();
  return fwd || req.socket.remoteAddress || 'unknown';
}

function loginBlocked(ip) {
  const r = loginFails.get(ip);
  if (!r) return false;
  if (Date.now() - r.first > LOGIN_WINDOW_MS) { loginFails.delete(ip); return false; }
  return r.count >= LOGIN_MAX_FAILS;
}

function recordLoginFail(ip) {
  const r = loginFails.get(ip);
  if (!r || Date.now() - r.first > LOGIN_WINDOW_MS) loginFails.set(ip, { count: 1, first: Date.now() });
  else r.count++;
}

// Same-origin check for state-changing requests.
function originOk(req) {
  const host = String(req.headers['x-forwarded-host'] || req.headers.host || '').split(',')[0].trim().toLowerCase();
  const origin = req.headers.origin;
  if (origin) {
    try { return new URL(origin).host.toLowerCase() === host || new URL(origin).host.toLowerCase() === String(req.headers.host || '').toLowerCase(); }
    catch (e) { return false; }
  }
  const site = req.headers['sec-fetch-site'];
  if (site && site !== 'same-origin' && site !== 'none') return false;
  return true;
}

setInterval(() => {
  const now = Date.now();
  for (const [k, s] of sessions) if (s.exp < now) sessions.delete(k);
  for (const [ip, r] of loginFails) if (now - r.first > LOGIN_WINDOW_MS) loginFails.delete(ip);
}, 10 * 60 * 1000).unref();

/* =====================================================================
 * 4. HTTP HELPERS
 * ===================================================================== */

function httpError(status, message) {
  const e = new Error(message);
  e.status = status;
  return e;
}

function baseHeaders(req, res) {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=()');
  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
  if (isHttps(req)) res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
}

function sendJSON(res, status, obj, extraHeaders) {
  const body = JSON.stringify(obj);
  res.writeHead(status, Object.assign({
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'Content-Length': Buffer.byteLength(body)
  }, extraHeaders || {}));
  res.end(body);
}

function csp(nonce) {
  return [
    "default-src 'none'",
    "script-src 'nonce-" + nonce + "'",
    "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
    "font-src https://fonts.gstatic.com",
    "img-src 'self' data: blob:",
    "connect-src 'self'",
    "base-uri 'none'",
    "form-action 'self'",
    "frame-ancestors 'none'"
  ].join('; ');
}

function sendHTML(res, html, nonce) {
  res.writeHead(200, {
    'Content-Type': 'text/html; charset=utf-8',
    'Cache-Control': 'no-store',
    'Content-Security-Policy': csp(nonce),
    'Content-Length': Buffer.byteLength(html)
  });
  res.end(html);
}

function readJSON(req) {
  return new Promise((resolve, reject) => {
    const ct = String(req.headers['content-type'] || '').toLowerCase();
    if (!ct.startsWith('application/json')) return reject(httpError(415, 'Content-Type must be application/json.'));
    const declared = parseInt(req.headers['content-length'] || '0', 10);
    if (declared > MAX_JSON_BYTES) return reject(httpError(413, 'Request body is too large.'));
    let size = 0;
    const chunks = [];
    let done = false;
    req.on('data', c => {
      if (done) return;
      size += c.length;
      if (size > MAX_JSON_BYTES) { done = true; reject(httpError(413, 'Request body is too large.')); req.resume(); return; }
      chunks.push(c);
    });
    req.on('end', () => {
      if (done) return;
      done = true;
      const text = Buffer.concat(chunks).toString('utf8');
      if (!text) return resolve({});
      try { resolve(JSON.parse(text)); }
      catch (e) { reject(httpError(400, 'Request body is not valid JSON.')); }
    });
    req.on('error', () => { if (!done) { done = true; reject(httpError(400, 'Request failed.')); } });
  });
}

function escapeHtml(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

/* =====================================================================
 * 5. VALIDATION
 * ===================================================================== */

function cleanText(s, multiline) {
  let out = s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').replace(/\r\n?/g, '\n');
  if (!multiline) out = out.replace(/\s+/g, ' ');
  else out = out.replace(/\n{3,}/g, '\n\n');
  return out.trim();
}

function validateProperty(b) {
  const errors = [];
  const v = {};
  if (!b || typeof b !== 'object' || Array.isArray(b)) return { errors: ['Invalid request body.'] };

  const text = (key, label, opt) => {
    let x = b[key];
    if (x == null) x = '';
    if (typeof x !== 'string') { errors.push(label + ' must be text.'); return ''; }
    x = cleanText(x, !!opt.multiline);
    if (opt.required && !x) { errors.push(label + ' is required.'); return ''; }
    if (x && opt.min && x.length < opt.min) errors.push(label + ' must be at least ' + opt.min + ' characters.');
    if (x.length > opt.max) errors.push(label + ' must be at most ' + opt.max + ' characters.');
    return x;
  };

  v.title = text('title', 'Property Title', { required: true, min: 3, max: 120 });

  const city = text('city', 'City', { required: true, max: 40 });
  if (city && city.toLowerCase() !== 'islamabad') errors.push('Only properties in Islamabad can be listed. City must be Islamabad.');
  v.city = 'Islamabad';

  const country = text('country', 'Country', { required: true, max: 40 });
  if (country && country.toLowerCase() !== 'pakistan') errors.push('Country must be Pakistan.');
  v.country = 'Pakistan';

  const areaName = text('area', 'Area/Sector', { required: true, max: 60 });
  const area = AREA_MAP.get(areaName);
  if (areaName && !area) errors.push('Area/Sector must be one of the approved Islamabad locations.');
  v.area = area ? area.name : '';
  if (b.ictConfirmed != null && typeof b.ictConfirmed !== 'boolean') errors.push('Location confirmation must be true or false.');
  v.ictConfirmed = !!(area && area.confirm && b.ictConfirmed === true);
  if (area && area.confirm && !v.ictConfirmed) {
    errors.push(area.name + ' may extend beyond Islamabad Capital Territory. Tick the confirmation box only after verifying that this specific property is inside Islamabad.');
  }

  v.address = text('address', 'Address/Location Description', { max: 200 });
  const other = v.address.match(OTHER_CITY_RE);
  if (other) errors.push('The address mentions "' + other[1] + '". Only properties located in Islamabad can be listed.');

  const type = b.type;
  if (!PROPERTY_TYPES.includes(type)) errors.push('Property Type is required.');
  v.type = PROPERTY_TYPES.includes(type) ? type : '';

  const purpose = b.purpose;
  if (!PURPOSES.includes(purpose)) errors.push('Purpose is required (For Sale or For Rent).');
  v.purpose = PURPOSES.includes(purpose) ? purpose : '';

  const size = text('size', 'Size', { max: 40 });
  v.size = size || null;

  let price = b.price;
  if (price === '' || price == null) v.price = null;
  else {
    if (typeof price === 'string') price = price.replace(/[,\s]/g, '');
    const n = (typeof price === 'string' && /^\d+$/.test(price)) ? Number(price) : (typeof price === 'number' ? price : NaN);
    if (!Number.isInteger(n) || n < 1 || n > 1e12) { errors.push('Price must be a whole number in PKR, or left empty.'); v.price = null; }
    else v.price = n;
  }

  v.description = text('description', 'Description', { max: 5000, multiline: true });

  let features = b.features;
  if (features == null || features === '') features = [];
  if (typeof features === 'string') features = features.split('\n');
  if (!Array.isArray(features)) { errors.push('Features must be a list.'); features = []; }
  const cleanFeatures = [];
  for (const f of features) {
    if (typeof f !== 'string') { errors.push('Each feature must be text.'); break; }
    const t = cleanText(f, false);
    if (!t) continue;
    if (t.length > 80) { errors.push('Each feature must be at most 80 characters.'); break; }
    cleanFeatures.push(t);
  }
  if (cleanFeatures.length > 30) errors.push('At most 30 features are allowed.');
  v.features = cleanFeatures.slice(0, 30);

  for (const k of ['featured', 'published']) {
    if (b[k] != null && typeof b[k] !== 'boolean') errors.push(k + ' must be true or false.');
    v[k] = b[k] === true;
  }
  return { errors, value: v };
}

/* =====================================================================
 * 6. PROPERTY VIEWS
 * ===================================================================== */

function sortProps(list) {
  return list.slice().sort((a, b) => (b.featured === true) - (a.featured === true) || String(b.updatedAt).localeCompare(String(a.updatedAt)));
}

function publicView(p) {
  return {
    id: p.id,
    title: p.title,
    city: p.city,
    area: p.area,
    address: p.address || '',
    type: p.type,
    purpose: p.purpose,
    size: p.size || null,
    price: Number.isInteger(p.price) ? p.price : null,
    description: p.description || '',
    features: Array.isArray(p.features) ? p.features : [],
    images: (p.images || []).map(n => '/images/' + n),
    featured: p.featured === true,
    updatedAt: p.updatedAt
  };
}

function adminView(p) {
  return Object.assign(publicView(p), {
    country: p.country,
    ictConfirmed: p.ictConfirmed === true,
    published: p.published === true,
    imageNames: (p.images || []).slice(),
    createdAt: p.createdAt
  });
}

/* =====================================================================
 * 7. ROUTE HANDLERS
 * ===================================================================== */

function requireAdmin(req, res, stateChanging) {
  if (!ADMIN_ENABLED) { sendJSON(res, 503, { error: 'Office login is disabled until ADMIN_PASSWORD is configured on the server.' }); return null; }
  const s = getSession(req);
  if (!s) { sendJSON(res, 401, { error: 'Please log in.' }); return null; }
  if (stateChanging) {
    if (!originOk(req)) { sendJSON(res, 403, { error: 'Request blocked.' }); return null; }
    const t = req.headers['x-csrf-token'];
    if (typeof t !== 'string' || !safeEqualStr(t, s.csrf)) { sendJSON(res, 403, { error: 'Security check failed. Please reload the page.' }); return null; }
  }
  return s;
}

function listPublic(req, res, url) {
  if (!storageOk) return sendJSON(res, 503, { error: 'Property listings are temporarily unavailable.' });
  const q = url.searchParams;
  const area = q.get('area') || '';
  const type = q.get('type') || '';
  const purpose = q.get('purpose') || '';
  const minS = (q.get('min') || '').replace(/[,\s]/g, '');
  const maxS = (q.get('max') || '').replace(/[,\s]/g, '');
  if (area && !AREA_MAP.has(area)) return sendJSON(res, 400, { error: 'Unknown location.' });
  if (type && !PROPERTY_TYPES.includes(type)) return sendJSON(res, 400, { error: 'Unknown property type.' });
  if (purpose && !PURPOSES.includes(purpose)) return sendJSON(res, 400, { error: 'Unknown purpose.' });
  if ((minS && !/^\d{1,13}$/.test(minS)) || (maxS && !/^\d{1,13}$/.test(maxS))) return sendJSON(res, 400, { error: 'Prices must be whole numbers.' });
  const min = minS ? Number(minS) : null;
  const max = maxS ? Number(maxS) : null;
  if (min != null && max != null && min > max) return sendJSON(res, 400, { error: 'Minimum price is higher than maximum price.' });

  let list = properties.filter(p => p.published === true);
  if (area) list = list.filter(p => p.area === area);
  if (type) list = list.filter(p => p.type === type);
  if (purpose) list = list.filter(p => p.purpose === purpose);
  if (min != null) list = list.filter(p => Number.isInteger(p.price) && p.price >= min);
  if (max != null) list = list.filter(p => Number.isInteger(p.price) && p.price <= max);
  sendJSON(res, 200, { properties: sortProps(list).map(publicView) });
}

function getPublic(res, id) {
  if (!storageOk) return sendJSON(res, 503, { error: 'Property listings are temporarily unavailable.' });
  const p = ID_RE.test(id) && properties.find(x => x.id === id && x.published === true);
  if (!p) return sendJSON(res, 404, { error: 'Property not found.' });
  sendJSON(res, 200, { property: publicView(p) });
}

async function handleLogin(req, res) {
  if (!ADMIN_ENABLED) return sendJSON(res, 503, { error: 'Office login is disabled until ADMIN_PASSWORD is configured on the server.' });
  if (!originOk(req)) return sendJSON(res, 403, { error: 'Request blocked.' });
  const ip = clientIp(req);
  if (loginBlocked(ip)) return sendJSON(res, 429, { error: 'Too many attempts. Please wait 15 minutes and try again.' });
  const body = await readJSON(req);
  const pw = typeof body.password === 'string' ? body.password.slice(0, 256) : '';
  if (!passwordMatches(pw)) {
    recordLoginFail(ip);
    await new Promise(r => setTimeout(r, 400));
    return sendJSON(res, 401, { error: 'Invalid login.' });
  }
  loginFails.delete(ip);
  const { token, csrf } = createSession();
  sendJSON(res, 200, { ok: true, csrf }, { 'Set-Cookie': sessionCookie(req, token, Math.floor(SESSION_TTL_MS / 1000)) });
}

function handleLogout(req, res) {
  const s = requireAdmin(req, res, true);
  if (!s) return;
  sessions.delete(s.key);
  sendJSON(res, 200, { ok: true }, { 'Set-Cookie': sessionCookie(req, '', 0) });
}

function handleStatus(req, res) {
  const s = ADMIN_ENABLED ? getSession(req) : null;
  sendJSON(res, 200, {
    enabled: ADMIN_ENABLED,
    authenticated: !!s,
    csrf: s ? s.csrf : null,
    storageOk,
    storageError: s ? storageError : (storageOk ? '' : 'Storage unavailable.'),
    storageWarning: s ? volumeWarning() : ''
  });
}

function newId() {
  let id;
  do { id = crypto.randomBytes(8).toString('hex'); } while (properties.some(p => p.id === id));
  return id;
}

async function createProperty(req, res) {
  const body = await readJSON(req);
  const { errors, value } = validateProperty(body);
  if (errors.length) return sendJSON(res, 422, { error: errors.join(' '), errors });
  const now = new Date().toISOString();
  const record = Object.assign({ id: newId() }, value, { images: [], createdAt: now, updatedAt: now });
  await mutate(list => { list.push(record); });
  sendJSON(res, 201, { property: adminView(record) });
}

async function updateProperty(req, res, id) {
  const body = await readJSON(req);
  const { errors, value } = validateProperty(body);
  if (errors.length) return sendJSON(res, 422, { error: errors.join(' '), errors });
  const updated = await mutate(list => {
    const p = list.find(x => x.id === id);
    if (!p) throw httpError(404, 'Property not found.');
    // Keep current publish/feature state unless the request sets it explicitly.
    if (typeof body.published !== 'boolean') value.published = p.published === true;
    if (typeof body.featured !== 'boolean') value.featured = p.featured === true;
    Object.assign(p, value, { updatedAt: new Date().toISOString() });
    return p;
  });
  sendJSON(res, 200, { property: adminView(updated) });
}

async function deleteProperty(req, res, id) {
  const removed = await mutate(list => {
    const i = list.findIndex(x => x.id === id);
    if (i < 0) throw httpError(404, 'Property not found.');
    return list.splice(i, 1)[0];
  });
  for (const n of removed.images || []) {
    if (IMAGE_NAME_RE.test(n)) fsp.unlink(path.join(IMG_DIR, n)).catch(() => {});
  }
  sendJSON(res, 200, { ok: true });
}

async function setFlag(req, res, id, flag) {
  const body = await readJSON(req);
  if (typeof body[flag] !== 'boolean') return sendJSON(res, 400, { error: flag + ' must be true or false.' });
  const updated = await mutate(list => {
    const p = list.find(x => x.id === id);
    if (!p) throw httpError(404, 'Property not found.');
    p[flag] = body[flag];
    p.updatedAt = new Date().toISOString();
    return p;
  });
  sendJSON(res, 200, { property: adminView(updated) });
}

function magicMatches(buf, ext) {
  if (ext === 'jpg') return buf.length >= 3 && buf[0] === 0xFF && buf[1] === 0xD8 && buf[2] === 0xFF;
  if (ext === 'png') return buf.length >= 8 && buf.slice(0, 8).equals(Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]));
  if (ext === 'webp') return buf.length >= 12 && buf.slice(0, 4).toString('ascii') === 'RIFF' && buf.slice(8, 12).toString('ascii') === 'WEBP';
  return false;
}

async function uploadImage(req, res, id) {
  if (!storageOk) return sendJSON(res, 503, { error: 'Storage is unavailable: ' + storageError });
  const ct = String(req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
  const ext = IMAGE_TYPES[ct];
  if (!ext) { req.resume(); return sendJSON(res, 415, { error: 'Only JPG, PNG or WebP photos are accepted.' }, { Connection: 'close' }); }
  const declared = parseInt(req.headers['content-length'] || '0', 10);
  if (declared > MAX_IMAGE_BYTES) { req.resume(); return sendJSON(res, 413, { error: 'Photo is larger than 8 MB.' }, { Connection: 'close' }); }
  const prop = properties.find(p => p.id === id);
  if (!prop) { req.resume(); return sendJSON(res, 404, { error: 'Property not found.' }); }
  if ((prop.images || []).length >= MAX_IMAGES_PER_PROPERTY) { req.resume(); return sendJSON(res, 400, { error: 'Maximum of ' + MAX_IMAGES_PER_PROPERTY + ' photos per property.' }); }

  const name = crypto.randomBytes(16).toString('hex') + '.' + ext;
  const finalPath = path.join(IMG_DIR, name);
  const tmpPath = finalPath + '.part';
  if (path.dirname(finalPath) !== IMG_DIR) return sendJSON(res, 400, { error: 'Invalid file name.' });

  try {
    await new Promise((resolve, reject) => {
      const ws = fs.createWriteStream(tmpPath, { flags: 'wx' });
      let size = 0;
      let failed = false;
      const fail = (err) => { if (failed) return; failed = true; ws.destroy(); req.resume(); reject(err); };
      req.on('data', chunk => {
        if (failed) return;
        size += chunk.length;
        if (size > MAX_IMAGE_BYTES) return fail(httpError(413, 'Photo is larger than 8 MB.'));
        if (!ws.write(chunk)) { req.pause(); ws.once('drain', () => req.resume()); }
      });
      req.on('end', () => { if (failed) return; if (size === 0) return fail(httpError(400, 'Empty upload.')); ws.end(); });
      req.on('aborted', () => fail(httpError(400, 'Upload was interrupted.')));
      req.on('error', () => fail(httpError(400, 'Upload failed.')));
      ws.on('error', () => fail(httpError(500, 'Could not save the photo.')));
      ws.on('finish', () => { if (!failed) resolve(); });
    });

    const fh = await fsp.open(tmpPath, 'r');
    const head = Buffer.alloc(12);
    try { await fh.read(head, 0, 12, 0); } finally { await fh.close(); }
    if (!magicMatches(head, ext)) throw httpError(415, 'The file is not a valid ' + ext.toUpperCase() + ' image.');

    await fsp.rename(tmpPath, finalPath);
    const updated = await mutate(list => {
      const p = list.find(x => x.id === id);
      if (!p) throw httpError(404, 'Property not found.');
      p.images = p.images || [];
      if (p.images.length >= MAX_IMAGES_PER_PROPERTY) throw httpError(400, 'Maximum of ' + MAX_IMAGES_PER_PROPERTY + ' photos per property.');
      p.images.push(name);
      p.updatedAt = new Date().toISOString();
      return p;
    });
    sendJSON(res, 201, { property: adminView(updated), image: name });
  } catch (e) {
    fsp.unlink(tmpPath).catch(() => {});
    fsp.unlink(finalPath).catch(() => {});
    const status = e.status || 500;
    sendJSON(res, status, { error: e.status ? e.message : 'Could not save the photo.' }, { Connection: 'close' });
  }
}

async function deleteImage(req, res, id, name) {
  if (!IMAGE_NAME_RE.test(name)) return sendJSON(res, 400, { error: 'Invalid image.' });
  const updated = await mutate(list => {
    const p = list.find(x => x.id === id);
    if (!p) throw httpError(404, 'Property not found.');
    const i = (p.images || []).indexOf(name);
    if (i < 0) throw httpError(404, 'Image not found.');
    p.images.splice(i, 1);
    p.updatedAt = new Date().toISOString();
    return p;
  });
  fsp.unlink(path.join(IMG_DIR, name)).catch(() => {});
  sendJSON(res, 200, { property: adminView(updated) });
}

function serveImage(req, res, name) {
  if (!IMAGE_NAME_RE.test(name) || !storageOk) { res.writeHead(404); return res.end(); }
  const owner = properties.find(p => (p.images || []).includes(name));
  if (!owner) { res.writeHead(404); return res.end(); }
  const isPublic = owner.published === true;
  if (!isPublic && !getSession(req)) { res.writeHead(404); return res.end(); }
  const file = path.join(IMG_DIR, name);
  if (path.dirname(file) !== IMG_DIR) { res.writeHead(404); return res.end(); }
  fs.stat(file, (err, st) => {
    if (err || !st.isFile()) { res.writeHead(404); return res.end(); }
    res.writeHead(200, {
      'Content-Type': IMAGE_MIME_BY_EXT[name.split('.').pop()],
      'Content-Length': st.size,
      'Cache-Control': isPublic ? 'public, max-age=86400' : 'private, no-store'
    });
    if (req.method === 'HEAD') return res.end();
    const rs = fs.createReadStream(file);
    rs.on('error', () => res.destroy());
    rs.pipe(res);
  });
}

/* =====================================================================
 * 8. ROUTER
 * ===================================================================== */

async function router(req, res) {
  baseHeaders(req, res);
  let url;
  try { url = new URL(req.url, 'http://localhost'); }
  catch (e) { return sendJSON(res, 400, { error: 'Bad request.' }); }
  const p = url.pathname;
  const m = req.method;
  const isGet = m === 'GET' || m === 'HEAD';

  if (isGet && (p === '/' || p === '/index.html')) { const n = nonce(); return sendHTML(res, publicPage(n), n); }
  if (isGet && (p === '/office' || p === '/office/')) { const n = nonce(); return sendHTML(res, officePage(n), n); }
  if (isGet && p === '/favicon.svg') {
    res.writeHead(200, { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'public, max-age=86400' });
    return res.end(FAVICON_SVG);
  }
  if (isGet && (p === '/logo.png' || p === '/favicon.png' || p === '/favicon.ico')) {
    const buf = p === '/logo.png' ? LOGO_PNG : FAVICON_PNG;
    if (!buf) { res.writeHead(404); return res.end(); }
    res.writeHead(200, { 'Content-Type': 'image/png', 'Content-Length': buf.length, 'Cache-Control': 'public, max-age=604800' });
    return res.end(m === 'HEAD' ? undefined : buf);
  }
  if (isGet && p === '/robots.txt') {
    res.writeHead(200, { 'Content-Type': 'text/plain' });
    return res.end('User-agent: *\nDisallow: /office\nDisallow: /api/admin/\n');
  }
  if (isGet && p.startsWith('/images/')) return serveImage(req, res, p.slice(8));

  if (p === '/api/health' && isGet) {
    return sendJSON(res, 200, { ok: true, storage: storageOk ? 'ok' : 'unavailable', adminConfigured: ADMIN_ENABLED });
  }
  if (p === '/api/properties' && isGet) return listPublic(req, res, url);
  let mm = p.match(/^\/api\/properties\/([^/]+)$/);
  if (mm && isGet) return getPublic(res, mm[1]);

  if (p === '/api/admin/status' && isGet) return handleStatus(req, res);
  if (p === '/api/admin/login' && m === 'POST') return handleLogin(req, res);
  if (p === '/api/admin/logout' && m === 'POST') return handleLogout(req, res);

  if (p === '/api/admin/properties') {
    if (isGet) {
      if (!requireAdmin(req, res, false)) return;
      if (!storageOk) return sendJSON(res, 503, { error: 'Storage is unavailable: ' + storageError });
      return sendJSON(res, 200, { properties: sortProps(properties).map(adminView) });
    }
    if (m === 'POST') { if (!requireAdmin(req, res, true)) return; return createProperty(req, res); }
    return sendJSON(res, 405, { error: 'Method not allowed.' });
  }

  mm = p.match(/^\/api\/admin\/properties\/([^/]+)(?:\/(publish|feature|images)(?:\/([^/]+))?)?$/);
  if (mm) {
    const [, id, action, sub] = mm;
    if (!ID_RE.test(id)) return sendJSON(res, 400, { error: 'Invalid property ID.' });
    if (!action && m === 'PUT') { if (!requireAdmin(req, res, true)) return; return updateProperty(req, res, id); }
    if (!action && m === 'DELETE') { if (!requireAdmin(req, res, true)) return; return deleteProperty(req, res, id); }
    if (action === 'publish' && m === 'POST' && !sub) { if (!requireAdmin(req, res, true)) return; return setFlag(req, res, id, 'published'); }
    if (action === 'feature' && m === 'POST' && !sub) { if (!requireAdmin(req, res, true)) return; return setFlag(req, res, id, 'featured'); }
    if (action === 'images' && m === 'POST' && !sub) { if (!requireAdmin(req, res, true)) { req.resume(); return; } return uploadImage(req, res, id); }
    if (action === 'images' && m === 'DELETE' && sub) { if (!requireAdmin(req, res, true)) return; return deleteImage(req, res, id, sub); }
    return sendJSON(res, 405, { error: 'Method not allowed.' });
  }

  if (p.startsWith('/api/')) return sendJSON(res, 404, { error: 'Not found.' });
  if (isGet) { const n = nonce(); return sendHTML(res, publicPage(n), n); } // unknown paths → homepage
  return sendJSON(res, 405, { error: 'Method not allowed.' });
}

function nonce() { return crypto.randomBytes(16).toString('base64'); }

/* =====================================================================
 * 9. SHARED FRONTEND PIECES (logo, CSS)
 * ===================================================================== */

const MARK_SVG = '<svg class="mark" viewBox="0 0 40 40" aria-hidden="true"><path d="M20 2 38 20 20 38 2 20Z" fill="#0b4d3b"/><path d="M20 2 38 20 20 20Z" fill="#8cc63f"/><path d="M2 20 20 20 20 38Z" fill="#14694f"/></svg>';
const FAVICON_SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><path d="M20 2 38 20 20 38 2 20Z" fill="#0b4d3b"/><path d="M20 2 38 20 20 20Z" fill="#8cc63f"/><path d="M2 20 20 20 20 38Z" fill="#14694f"/></svg>';

// Embedded images are decoded once and served from /logo.png and /favicon.png.
function dataUriToBuffer(uri) {
  const m = /^data:image\/png;base64,([A-Za-z0-9+/=]+)$/.exec(uri || '');
  return m ? Buffer.from(m[1], 'base64') : null;
}
const LOGO_PNG = dataUriToBuffer(LOGO_DATA_URI);
const FAVICON_PNG = dataUriToBuffer(FAVICON_DATA_URI);

function logoHTML(light) {
  if (LOGO_PNG) {
    return '<img class="logo-img' + (light ? ' on-dark' : '') + '" src="/logo.png" alt="Alhijjab Marketing" width="347" height="96">';
  }
  return MARK_SVG + '<span class="word' + (light ? ' light' : '') + '">Alhijjab Marketing</span>';
}

function clientConfig() {
  const cfg = { areas: AREAS, types: PROPERTY_TYPES, purposes: PURPOSES, contact: CONTACT, minPassword: MIN_PASSWORD_LENGTH };
  return JSON.stringify(cfg).replace(/</g, '\\u003c');
}

